import { DatePipe } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertController } from '@ionic/angular';
import { AlertService } from 'src/app/services/alert.service';
import { UserService } from 'src/app/services/emis/user.service';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
import { NetworkService } from 'src/app/services/tnvn/services/network.service';

import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-mht-class-list',
  templateUrl: './mht-class-list.page.html',
  styleUrls: ['./mht-class-list.page.scss'],
})
export class MhtClassListPage implements OnInit {

  pipe = new DatePipe('en-US');
  routeData: any;
  paramsId: any;
  classActive: boolean;
  sectionActive: boolean;
  todayDate: any;
  todayDateFormat: any;
  school_id: any;
  emis_username: any;
  school_name: any;
  todaystatusData: any;
  emis_usertype: number;
  classList: any[];
  allClassLists: any;
  classLength: any;
  classSync: any;
  classVal: any;
  section: any;
  sectionList: any;
  classId: any;
  class_in_roman: any = ["0", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII", "LKG", "UKG", "PREKG"];
  sectionsList: any[];
  SchlId: any;
  SchName: any;
  UserName: any;
  StudentsCounts: any=[];
  acYear: any;
  classCountDet: any[] = [];
  viewType: any;
  Latt: any;
  Longg: any;

  constructor(private router: Router, private alertController: AlertController,
    private route: ActivatedRoute, private alertService: AlertService,
    private usersessionService: UserSessionService, private networkService: NetworkService,
    private sqliteDB: SqlitedatabaseService,private userService:UserService) { }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.routeData = this.route.snapshot;
    this.paramsId = this.routeData.queryParams.Id;
    this.SchlId= this.routeData.queryParams.SchlId;
    this.SchName= this.routeData.queryParams.SchName;
    this.acYear= this.routeData.queryParams.acYear;
    this.Latt = this.routeData.queryParams.Latt;
    this.Longg = this.routeData.queryParams.Longg;
    this.UserName = this.usersessionService.emis_username();
    this.viewType = localStorage.getItem("viewType");

    if (this.paramsId == 1) {
      this.classActive = false;
      this.sectionActive = true;
    } else {
      this.classActive = true;
      this.sectionActive = false;
    }

    this.todayDate = this.pipe.transform(new Date(), 'dd-MM-yyyy');
    this.todayDateFormat = this.pipe.transform(new Date(), 'yyyy-MM-dd');
    // this. totalStudentcheckLocalDb();
   this. totalStudentsCount();

  }

  totalStudentcheckLocalDb() {
    let query = 'SELECT * FROM mhtStudentCountDB WHERE SchlId=' + this.SchlId;
    return this.sqliteDB.getDataLocalDB(query).then(data => {
      if (data.rows.length > 0) {
        this.StudentsCounts = [];
        for (var i = 0; i < data.rows.length; i++) {
          this.StudentsCounts.push(data.rows.item(i));
        }
      } else {
        this.totalStudentsCount()
      }
    });
  }

  totalStudentsCount(){
    this.StudentsCounts = [];
    this.classCountDet = [];
    this.userService.mhtStudentsCount(this.UserName,this.SchlId, this.acYear).subscribe((res) => {
      if (res.dataStatus) {
        this.StudentsCounts = res.result;
        this.classCountDet = res.result[0]['class_count'];
        // this.TotalStudinsertLocalDB(this.StudentsCounts)
      }
      this.checkLocalData();
    });
  }
 
  checkLocalData() {
    this.classList = [];
    this.allClassLists=[];
    this.sqliteDB.getExistData('AllClasslist', this.SchlId, 'SchlD').then((res) => {
      if (res.length > 0) {
        this.allClassLists = res;
        this.classList = Array.from(new Set(this.allClassLists.map(s => s.ClsID)))
          .map(ClsID => {
            var stuCount = this.classCountDet.filter(x=> x.class_studying_id == ClsID);
            return {
              ClsID: ClsID,
              Clsroman: this.allClassLists.find(s => s.ClsID == ClsID).Clsroman,
              Sync: this.allClassLists.find(s => s.ClsID == ClsID).Sync,
              SyncClass: this.allClassLists.find(s => s.ClsID == ClsID).SyncClass,
              Synclr: '',
              present: this.allClassLists.find(s => s.ClsID == ClsID).present,
              absent: this.allClassLists.find(s => s.ClsID == ClsID).absent,
              stuCount: stuCount.length > 0 ? +stuCount[0]['TotalStudents'] : 0
            }
          });
        this.classList.forEach(a => {
          this.classLength = this.allClassLists.filter(tt => tt.ClsID == a.ClsID);
          this.classSync = this.allClassLists.filter(tt => tt.ClsID == a.ClsID && tt.SyncClass == 1);
          if (this.classLength.length == this.classSync.length) {
            a.Synclr = 1;
          } else {
            a.Synclr = 0;
          }
        });
        this.classList.sort((a, b) => {
          if (a.ClsID < b.ClsID)
            return -1;
          if (a.ClsID > b.ClsID)
            return 1;
          return 0;
        });
      }
      else {
       // this.router.navigate(['tabs/attendance/sync-settings']);
        this.alertService.error("Please Sync Student List");
      }
    });
  }

  classSelected(value: any) {
    if(this.acYear == '2023-24'){
      this.classVal = value.ClsID;
      this.goToStudentAttendance('');
    }
    else{
      this.goToSection(value);
    }
  }

  goToSection(data) {
    this.sectionList = [];
    this.classVal = data.ClsID;
    this.sectionsList = this.allClassLists.filter(tt => tt.ClsID == this.classVal);
    const key = 'Sectn';
    this.sectionList = [...new Map(this.sectionsList.map(item =>
      [item[key], item])).values()];
    this.classId = this.class_in_roman[this.classVal];
    if (this.sectionList.length > 0) {
      this.sectionActive = true;
      this.classActive = false;
    }
  }

  goToStudentAttendance(section) {
    this.section = section?.Sectn;
   this.router.navigate(['/tabs/class-student-list'], { queryParams: { 'SchlId': this.SchlId, 'Latt':this.Latt, 'Longg': this.Longg, 'ClsID': this.classVal, 'Sectn': this.section, 'SchName': this.SchName, 'session': 1, 'acYear': this.acYear }, skipLocationChange: false });
  }

  moveClass() {
    this.sectionActive = false;
    this.classActive = true;
  }


  goToDashboard() {
    this.router.navigate(['/tabs/school-list-mht']);
  }


  onSync(){
    let connectionStatus = this.networkService.getCurrentNetworkStatus();
    if (connectionStatus !== 1) {
      let deleteQuery = 'DELETE FROM AllClasslist WHERE SchlD = ' + this.SchlId;
      return this.sqliteDB.getDataLocalDB(deleteQuery).then(data => {
        this.getAllClassList();
      });
    } else {
      this.alertService.error("Internet not available, Cross check your internet connectivity and try again");
    }
  }


  getAllClassList() {
    this.userService.getAllClassList(2, this.SchlId).subscribe((res) => {
      if (res) {
        res.map(i => i['Clsroman'] = this.class_in_roman[i['class_id']]);
        if (res.length > 0) {
          res.forEach(element => {
            this.saveClassLocalDB(this.SchlId, element.class_id, element.section, element.Clsroman);
          });
          this.getClassLocalDB();
        }
      }
    });
  }

  saveClassLocalDB(SchlD, ClsID, Sectn, Clsroman) {
    const datainsert = 'INSERT INTO AllClasslist VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)';
    this.sqliteDB.insert(datainsert, [null, SchlD, ClsID, Sectn, Clsroman, this.SchlId, 0, 0, 0, 0, 0, 0, this.todayDate, 0, 0]).then(insertres => {
      if (insertres) {
      }
    });
  }


  TotalStudinsertLocalDB(key) {
    key.forEach((element,) => {
      const datainsert = 'INSERT INTO mhtStudentCountDB VALUES (?,?,?,?,?,?)';
      this.sqliteDB.insert(datainsert, [null, element.DocAddedStudents, element.ScreenedStudents,element.TotalStudents, element.UnScreenedStudents, this.SchlId]).then(insertres => {
        if (insertres.insertId) {
        }
      });
    });
  }
  getClassLocalDB() {
    this.sqliteDB.getExistData('AllClasslist', this.SchlId, 'userName').then((res) => {
      if (res.length > 0) {
       this.ionViewDidEnter();
      }
    });
  }


}
